fn main() {
    let mut scores: Vec<i32> = Vec::new();
    scores.push(80);
    scores.push(95);
    scores.push(72);
    println!("{:?} has {} items", scores, scores.len());

    let primes = vec![2, 3, 5, 7];   // vec! makes one with values
    println!("{:?}", primes);
}

fn main() {
    let names = vec!["An", "Binh", "Chi"];
    println!("{}", names[1]);
    match names.get(10) {
        Some(n) => println!("found {n}"),
        None => println!("no item at 10"),
    }
}

fn main() {
    let mut prices = vec![10, 20, 30];
    for p in &mut prices {
        *p += 1;
    }
    for p in &prices {
        println!("{p}");
    }
    let last = prices.pop();   // removes and returns Some(31)
    println!("{:?} {:?}", last, prices);
}

